import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-008 — Star panel: one hero, the constellation finder in an \\"In the sky\\" tab, a Gallery tab for more","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-008-star-panel-one-hero-and-in-the-sky-tab.md","filePath":"uxs/decisions/UXD-008-star-panel-one-hero-and-in-the-sky-tab.md"}'),r={name:"uxs/decisions/UXD-008-star-panel-one-hero-and-in-the-sky-tab.md"};function i(s,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="uxd-008-—-star-panel-one-hero-the-constellation-finder-in-an-in-the-sky-tab-a-gallery-tab-for-more" tabindex="-1">UXD-008 — Star panel: one hero, the constellation finder in an &quot;In the sky&quot; tab, a Gallery tab for more <a class="header-anchor" href="#uxd-008-—-star-panel-one-hero-the-constellation-finder-in-an-in-the-sky-tab-a-gallery-tab-for-more" aria-label="Permalink to &quot;UXD-008 — Star panel: one hero, the constellation finder in an &quot;In the sky&quot; tab, a Gallery tab for more&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-11 (the operator&#39;s point and clarification, then the go)</li><li><strong>Decider</strong>: the operator raised the point (SN2, <code>docs/wip/2026-11-11-ux-feedback-plan.md</code> line 206: &quot;all images placed on top push the overview down … one hero image, a gallery tab for more images, and a dedicated pattern for linking stars to zodiac signs&quot;) and, on the Antares screenshot, clarified that &quot;the zodiac chart&quot; is the constellation finder figure (lines 432–437). The tab layout is the lead&#39;s resolution (slice B3). The operator, 2026-11-11 (session go after the UXD check), recorded in <code>docs/wip/2026-11-11-ux-feedback-plan.md</code>, line starting &quot;- Operator go, 2026-11-11 (session&quot; (line 460): the fixes for W6, SN2, G5/G6 and O6 &quot;are accepted as decided&quot;.</li><li><strong>Answers</strong>: SN2; slice B3 (outer panels and stars)</li><li><strong>Changes</strong>: UXS-001 (detail panel tabs; no star-panel section today) and UXS-014 §Selecting and understanding an object (see UXS-000 §Next).</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>StarPanel</code> stacks the constellation finder figure (&quot;Scorpius from the Sun&#39;s sky&quot;) under the star portrait and above the tabs; together they push Overview below the fold (plan lines 432–434). The planet panels already follow one pattern: one hero, a Gallery tab for more images.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>The sources record one layout and no alternatives.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The star panel follows the planet pattern:</p><ol><li><strong>One hero at the top</strong>: the photo if there is one, otherwise the portrait.</li><li><strong>The constellation finder in its own tab, &quot;In the sky&quot;</strong>, with the constellation named and linked.</li><li><strong>A Gallery tab when the star has more than one image.</strong></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Slice B3 applies the same pattern to the outer-level panels (Milky Way, Local Group, Laniakea) so their panels match the others (MW3), and uses deep-sky images as heroes where one exists (MW5).</li><li>Related items on the same screen belong to other slices: the &quot;5 LY&quot; ring label colliding with &quot;Barnard&#39;s Star&quot; (C2, label declutter) and the italic lead (A1, <a href="./UXD-002-type-scale-and-the-11px-floor">UXD-002</a>).</li><li>The Sagittarius A* panel (MW3) is clarified in the plan (EHT 2022 image as hero, lensing render as an explicit action) but not recorded as an operator decision; it is not part of this record (UXS-000 §Open).</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Planned in slice B3: shots of a star with photo and of the outer panels. No test guards the tab layout today (not checked by this document).</p>',13)])])}const f=t(r,[["render",i]]);export{u as __pageData,f as default};
